function pendingPdfCard(title){return `<div class="managed-pdf-card is-unavailable" aria-disabled="true"><span class="managed-pdf-number" aria-hidden="true">—</span><span class="managed-pdf-icon" aria-hidden="true">${collegeDocumentIcon()}</span><span class="managed-pdf-copy"><b>${escapeHtml(title)}</b><small>PDF not available yet</small></span><span class="managed-pdf-arrow" aria-hidden="true">↗</span></div>`}

function enquiryFormButton(label='Enquiry Form'){return `<a class="btn btn-primary" href="${ADMISSIONS_ENQUIRY_URL}" target="_blank" rel="noopener noreferrer">${escapeHtml(label)} →</a>`}


function layout(content){return header()+content+footer()}

function page(title,sub,body){const admissionTypography=['Course & Eligibility','Forms & Brochure','Fee Structure','Admission Links'].includes(title)?' admission-page-typography':'';return layout(`<section class="page-hero${admissionTypography}"><div class="container"><div class="breadcrumbs">Home / ${title}</div><h1>${title}</h1><p>${sub}</p></div></section>${body}`)}

function about(){return page('About Shakuntalam','A growing learning community, founded on opportunity, practical preparation and the belief that education shapes the future.',`<section class="section about-opening"><div class="container about-feature-grid"><article class="card about-story-card">${aboutPhotoMarkup()}<span class="kicker">Our story</span><h2>Rooted in education. Preparing for what comes next.</h2><p>Shakuntalam Group of Institutions is a learning community dedicated to helping students build knowledge, confidence and practical skills. The story began with Devi Shakuntalam Pratishthan in 2009, followed by the establishment of Shakuntalam Institute of Teachers Education in 2015.</p><p>Located at Kumhau Station Road in Sasaram, Rohtas, Bihar, the institute focuses on preparing thoughtful and capable educators. Its work brings academic study together with practice, mentorship and a supportive campus experience.</p></article><aside class="card about-facts-card"><span class="kicker">Our journey · 2009—2026</span><div class="about-years-highlight"><strong>17</strong><span><b>Years of excellence</b><small>Growing with purpose since 2009</small></span></div><div class="about-fact"><strong>2009</strong><span><b>Devi Shakuntalam Pratishthan Founded</b><small>Devi Shakuntalam Pratishthan continues its educational work</small></span></div><div class="about-fact"><strong>2010</strong><span><b>Shakuntalam Industrial Training Institute Established</b><small>Expanding practical skill training opportunities</small></span></div><div class="about-fact"><strong>2015</strong><span><b>Shakuntalam Institute of Teachers Education Established</b><small>A dedicated home for aspiring educators</small></span></div><div class="about-fact"><strong>2023</strong><span><b>Introduction to Vocational Courses</b><small>BBA &amp; BCA as new pathways in management and computing</small></span></div><div class="about-fact"><strong>2026</strong><span><b>Shakuntalam City Campus</b><small>Expanded learning opportunities in city centre, Sasaram</small></span></div><div class="about-fact"><strong>04</strong><span><b>Academic programmes</b><small>Four pathways in teacher education, management and computing</small></span></div><div class="about-fact"><strong>03</strong><span><b>Connected fields. One shared purpose.</b><small>Teacher Education &amp; Business Management &amp; Computing</small></span></div></aside></div></section><section class="section about-section"><div class="container about-copy-below"><div><span class="kicker">A purpose that lasts</span><h2>Education with care, curiosity and responsibility.</h2><p class="lead">Teacher education is about more than a qualification. It is preparation to guide learners, encourage questions and make a lasting contribution to the community.</p><p class="muted">The institute aims to nurture educators who combine a sound academic foundation with empathy, clear communication and a commitment to continual learning. Students are encouraged to grow as individuals while preparing for the responsibilities of the teaching profession.</p><a class="btn btn-primary btn-burgundy" href="#/leadership">Meet our leadership →</a></div></div></section><section class="section about-section about-tint"><div class="container"><div class="section-head"><div><span class="kicker">Learning by doing</span><h2>Build understanding in the classroom and beyond.</h2></div></div><div class="about-pillar-grid"><article class="card about-pillar"><span class="numbered-card-badge about-pillar-number">01</span><h3>Strong foundations</h3><p>Coursework supports understanding of educational ideas, learners and the responsibilities of teaching.</p></article><article class="card about-pillar"><span class="numbered-card-badge about-pillar-number">02</span><h3>Practice and reflection</h3><p>Teaching practice and internship experiences help students apply learning in real classroom settings and reflect on their growth.</p></article><article class="card about-pillar"><span class="numbered-card-badge about-pillar-number">03</span><h3>Guidance and mentorship</h3><p>Experienced educators share knowledge, offer guidance and help aspiring teachers connect theory with professional practice.</p></article></div></div></section><section class="section about-section"><div class="container about-copy-below about-facilities"><div><span class="kicker">The learning environment</span><h2>Space to learn, practice and collaborate.</h2><p class="muted">The college describes a campus designed to support focused study and hands-on learning. Classrooms, laboratories and a resource-rich library contribute to an environment where students can explore ideas, work together and build practical understanding.</p><p class="muted">Learning also extends through workshops, teaching internships and professional development. These experiences help students become familiar with classroom responsibilities and stay engaged with evolving approaches to education and technology.</p><a class="btn btn-outline" href="#/facilities">Explore Campus Facilities →</a></div></div></section><section class="section about-section about-tint about-community-section"><div class="container about-community about-copy-below"><div><span class="kicker">A community beyond graduation</span><h2>Grow with people who support your journey.</h2><p class="lead">A positive college experience depends on encouragement, shared effort and a sense of belonging.</p><p class="muted">Students learn alongside peers, receive guidance from faculty and build relationships that can continue well beyond their studies. The institution values a welcoming environment where learners can develop confidence, support one another and prepare to serve their communities as educators.</p><div class="about-values"><span>Supportive learning</span><span>Practical preparation</span><span>Professional growth</span><span>Community connection</span></div></div></div></section><section class="section about-section about-next-section"><div class="container about-next"><div><span class="kicker">Your next chapter</span><h2>Find the path that fits your ambitions.</h2><p class="muted">Explore teacher education programs, learn about the wider group of institutions or contact the college for guidance about admissions and student support.</p></div><div class="about-next-actions"><a class="btn btn-primary" href="#/departments">Explore departments →</a><a class="btn btn-outline" href="#/contact">Contact the college →</a></div></div></section>`)}

function mission(){const values=[['01','Integrity','Build trust through honest academic work, fair decisions and responsible use of information. Keep commitments, acknowledge mistakes, and treat students, colleagues and community members with respect and consistency in everyday learning and service.'],['02','Excellence','Pursue strong learning through preparation, steady effort and reflection. Welcome constructive feedback, set clear goals, and keep improving academic work and practical skills instead of treating achievement as a one-time result.'],['03','Innovation','Stay curious, ask useful questions and explore more than one way to solve a problem. Apply creative thinking to real learning challenges, evaluate what works, and share ideas that can improve teaching and practice.'],['04','Inclusion','Create space for people with different backgrounds, abilities and perspectives to participate. Listen with care, use respectful language, and support fair opportunities so each learner can contribute and feel part of the community.'],['05','Practical Learning','Connect ideas from study with hands-on tasks, classroom experience, projects and reflection. Practise skills in relevant settings, learn from guidance, and use what you discover to strengthen understanding and confidence.'],['06','Service','Contribute time, knowledge and care to the campus and wider community. Notice where help is needed, work cooperatively, and use learning responsibly in ways that support others and encourage a shared sense of purpose.']];return page('Mission, Vision & Core Values','Vision, mission and shared values for learning, professional preparation and community participation.',`<section class="section"><div class="container mission-page"><div class="mission-statement-grid"><article class="card mission-statement-card mission-vision"><span class="numbered-card-badge mission-index">01</span><span class="kicker">Vision</span><h2>A learning community where every learner can grow with purpose.</h2><p>To support learners as they build knowledge, confidence and practical ability, and prepare to contribute thoughtfully to their communities.</p></article><article class="card mission-statement-card mission-purpose"><span class="numbered-card-badge mission-index">02</span><span class="kicker">Mission</span><h2>Make learning relevant, welcoming and connected to practice.</h2><p>To offer an encouraging educational environment with strong academic foundations, hands-on learning, guidance and opportunities for continuous development.</p></article></div><div class="mission-values-heading"><span class="kicker">Shared principles</span><h2>Core Values</h2><p>Ways to support learning, professional practice and community life.</p></div><div class="mission-values-grid">${values.map(([n,title,copy])=>`<article class="card mission-value-card"><span class="numbered-card-badge mission-value-number">${n}</span><h3>${title}</h3><p>${copy}</p></article>`).join('')}</div></div></section>`)}

function departments(){
 const items=[
  {name:'Department of Teachers Education',courses:['B.Ed.','D.El.Ed.'],copy:'Prepare to support confident, curious learners through the study of child development and effective teaching. Connect educational ideas with lesson planning, classroom practice and reflection. Build the skills to make learning inclusive, engaging and purposeful.',slug:'teachers-education',badge:'Affiliated By: VKSU & Recognised By: NCTE & BSEB'},
  {name:'Department of Management',courses:['BBA','BCA'],copy:'Explore business, management and computing through a practical, career-focused learning experience. Strengthen communication, teamwork and problem-solving alongside core academic knowledge. Develop the confidence to contribute to organisations, technology and new ideas.',slug:'management',badge:'Affiliated By: VKSU & Recognised By: AICTE'}
 ];
 return page('Departments & Programs','Explore focused pathways in teacher education, management and computing.',`<section class="section"><div class="container"><div class="department-list-grid">${items.map((d,i)=>`<article class="card department-list-card"><span class="numbered-card-badge department-card-number">0${i+1}</span><div class="department-list-copy"><div class="department-card-top"><span class="pill department-affiliation-pill">${d.badge}</span></div><h2>${d.name}</h2><p class="muted">${d.copy}</p><div class="department-course-tags">${d.courses.map(c=>`<span>${c}</span>`).join('')}</div><a class="btn btn-primary" href="#/department/${d.slug}">Explore Department →</a></div></article>`).join('')}</div></div></section>`)
}

function course(name){
 if(['Electrician','Fitter'].includes(String(name).trim()))return page('Course information unavailable','For current programme information, please contact the college.',`<section class="section"><div class="container"><a class="btn btn-primary" href="#/contact">Contact Us →</a></div></section>`);
 const c=courses.find(x=>x[0]===name)||courses[0];
 const profiles={
  'B.Ed.':{title:'Bachelor of Education',tagline:'Develop the knowledge and classroom confidence to guide the next generation.',focus:'Child development, learning theory and subject pedagogy',practice:'Lesson planning, teaching practice, assessment and supervised school internship',pathway:'Prepares learners for school teaching and related education roles.',image:img.campus,cardTitle:'Prepare to teach with purpose.'},
  'D.El.Ed.':{title:'Diploma in Elementary Education',tagline:'Build a strong foundation for teaching and supporting elementary learners.',focus:'Foundational learning, child development and elementary pedagogy',practice:'Activity-based lesson design, classroom observation and teaching practice',pathway:'Builds practical preparation for elementary education settings.',image:img.class,cardTitle:'Support the earliest years of learning.'},
  'BBA':{title:'Bachelor of Business Administration',tagline:'Explore how organizations work and strengthen the skills to lead and collaborate.',focus:'Management, marketing, finance, communication and entrepreneurship',practice:'Business cases, presentations, collaborative projects and digital tools',pathway:'Develops a foundation for business roles and further management study.',image:img.campus,cardTitle:'Build skills for a changing business world.'},
  'BCA':{title:'Bachelor of Computer Applications',tagline:'Turn curiosity about technology into practical computing and problem-solving skills.',focus:'Programming, databases, web technologies and computer applications',practice:'Computer laboratory work, coding exercises and application projects',pathway:'Creates a foundation for entry-level computing roles and further study.',image:img.class,cardTitle:'Learn by building with technology.'},
  'Electrician':{title:'Electrician',tagline:'Learn electrical fundamentals through structured workshop-based training.',focus:'Electrical circuits, wiring, installation, machines and safety',practice:'Tool handling, wiring exercises, measurement and maintenance practice',pathway:'Builds trade skills for electrical installation and maintenance work.',image:img.lab,cardTitle:'Gain practical electrical trade skills.'},
  'Fitter':{title:'Fitter',tagline:'Develop precision, workshop confidence and practical mechanical skills.',focus:'Engineering drawings, fitting, measurement and workshop technology',practice:'Marking, cutting, filing, assembly and safe tool use',pathway:'Builds trade skills for fitting, assembly and workshop environments.',image:img.lab,cardTitle:'Shape ideas into precise workmanship.'}
 };
 const profile=profiles[c[0]]||{title:c[0],tagline:c[2],focus:c[1],practice:'Guided coursework and practical learning',pathway:'Builds a foundation for further study and related work.',image:img.campus,cardTitle:`Explore the ${c[0]} programme.`};
 const snapshot=[['Duration',c[3]],['Department',c[1]],['Mode','Campus Programme'],['Course Focus',profile.focus],['Practical Learning',profile.practice],['Progression',profile.pathway]];
 return page(profile.title,`${c[1]} · ${c[3]}`,`<section class="section course-showcase-section"><div class="container course-showcase-grid"><article class="card course-overview-card">${coursePhotoMarkup(c[0],profile.title)}<div class="course-overview-content"><span class="kicker">Explore the programme</span><h2>${profile.cardTitle}</h2><p class="course-lead">${profile.tagline}</p><p class="muted">${c[2]}</p><div class="course-highlight-row"><span>01&nbsp; Build strong foundations</span><span>02&nbsp; Learn through practice</span><span>03&nbsp; Prepare for your next step</span></div><a class="btn btn-primary" href="#/admissions">Apply for ${c[0]} →</a></div></article><article class="card course-snapshot-card"><div class="course-snapshot-heading"><span class="kicker">Programme at a glance</span><h2>Program Snapshot</h2><p class="muted">A quick guide to what you will study and experience.</p></div><div class="course-snapshot-list">${snapshot.map(([label,value],i)=>`<div class="course-snapshot-row" style="--course-row-index:${i}"><span>${label}</span><b>${value}</b></div>`).join('')}</div><div class="course-snapshot-note"><p><b>Learn with support.</b> Contact the college for course notices, attendance, assignments and results information.</p></div></article></div></section>`)
}

function notices(){return page('Notice','Admissions, examinations, academic schedules and campus announcements.',`<section class="section"><div class="container"><div class="card"><h2>College Notices</h2><p class="muted">Please contact the college office for current notices and academic announcements.</p><a class="btn btn-outline" href="#/contact">Contact the College</a></div></div></section>`)}

function facilities(){return page('Facilities','Explore the learning, study and campus facilities available to the college community.',`<section class="section"><div class="container grid-4">${campusFacilityPages.map((facility,index)=>`<a class="facility card" href="#/facilities/${facility.slug}"><span class="numbered-card-badge">${String(index+1).padStart(2,'0')}</span><h3>${facility.title}</h3><p class="muted">Read about the ${facility.title.toLowerCase()} and its role in campus life.</p><span class="facility-card-link">Explore facility →</span></a>`).join('')}</div></section>`)}

function facilityDetailPage(slug){const facility=campusFacilityPages.find(item=>item.slug===slug);if(!facility)return facilities();return page(facility.title,`Learn about the ${facility.title.toLowerCase()} and how it supports student learning and campus life.`,`<section class="section"><div class="container facility-detail-page"><a class="back-link" href="#/facilities">← All Facilities</a><article class="card facility-detail-card"><span class="kicker">Campus Facilities</span><h2>${facility.title}</h2><div class="facility-detail-copy">${facility.paragraphs.map(text=>`<p>${text}</p>`).join('')}</div></article></div></section>`)}

function gallery(){return page('Campus Gallery','A visual showcase section ready for real campus photography.',`<section class="section"><div class="container gallery">${[[img.campus,'Shakuntalam College campus'],[img.class,'College annual day programme'],[img.library,'Academic seminar at Shakuntalam College'],[img.lab,'Students taking an examination'],[img.students,'Shakuntalam College faculty and students'],[img.hero,'Shakuntalam College campus building']].map(([src,alt])=>`<img src="${src}" alt="${alt}" width="1444" height="1084" loading="lazy" decoding="async">`).join('')}</div></section>`)}

function contact(){
 const locations=[{kicker:'Teacher Education',name:'Shakuntalam Institute of Teachers Education',address:'Kirhindih Road, Sasaram, Rohtas-821111',phones:['9470014145','8789036195']},{kicker:'BBA & BCA Department',name:'Shakuntalam College (City Campus)',address:'Bauliya More, Jagdev Path, Sasaram, Rohtas-821115',phones:['9470014145','8789036195']}];
 return page('Contact & Locations','Connect with admissions, academics or the administration office.',`<section class="section contact-locations"><div class="container"><div class="locations-grid">${locations.map(x=>`<article class="card location-card"><div class="location-card-head"><span class="location-card-icon" aria-hidden="true">${graduationCapIcon}</span><div class="location-card-title"><span class="kicker">${x.kicker}</span><h2>${x.name}</h2></div></div><div class="location-details"><div class="location-detail"><div><b>Address</b><span>${x.address}</span></div></div><div class="location-detail"><div><b>Contact</b><span class="location-phone-list">${x.phones.map(n=>`<a href="tel:${n}">${n}</a>`).join('<span class="phone-separator">&amp;</span>')}</span></div></div></div></article>`).join('')}</div><div class="card contact-enquiry"><div class="contact-enquiry-copy"><span class="kicker">Get in touch</span><h2>Enquiry Form</h2><p class="muted">Send your admissions, course or campus enquiry through the college enquiry form.</p>${enquiryFormButton('Enquiry Form')}</div></div></div></section>`)
}

function admissions(){
 const programmes=courses.slice(0,4);
 const programmeCards=programmes.map((course,index)=>`<article class="card admission-style-card"><span class="numbered-card-badge">0${index+1}</span><div class="admission-style-copy"><span class="kicker">${escapeHtml(course[1])} · ${escapeHtml(course[3])}</span><h2>${escapeHtml(course[0])}</h2><p>${escapeHtml(course[2])}</p><a class="btn btn-outline" href="#/course/${encodeURIComponent(course[0])}">Course information →</a></div></article>`).join('');
 return page('Admissions 2026–27','Explore the available programmes and follow the current official admission instructions.',`<section class="section"><div class="container admission-policy-page"><article class="card admission-intro-card"><div class="admission-intro-copy"><span class="kicker">Admissions introduction</span><h2>Choose the programme that fits your plans.</h2></div>${enquiryFormButton('Enquiry Form')}</article><section class="admission-programmes-section" aria-labelledby="admission-programmes-heading"><div class="section-head"><div><span class="kicker">Departments &amp; programmes</span><h2 id="admission-programmes-heading">Programmes at Shakuntalam</h2></div></div><div class="admission-policy-grid">${programmeCards}</div></section><section class="admission-guidance-section" aria-labelledby="admission-guidance-heading"><div class="section-head"><div><span class="kicker">Admission guidance</span><h2 id="admission-guidance-heading">Plan your application</h2></div></div><div class="admission-policy-grid"><article class="card admission-style-card"><span class="numbered-card-badge">01</span><div class="admission-style-copy"><span class="kicker">Eligibility criteria</span><h2>Check the current notice.</h2><p>Eligibility depends on the programme and applicable university or regulatory requirements. Use the current official notice or contact the admission office.</p><a class="btn btn-outline" href="#/admission-links">View Admission Link</a></div></article><article class="card admission-style-card"><span class="numbered-card-badge">03</span><div class="admission-style-copy"><span class="kicker">Required documents</span><h2>Prepare the records requested.</h2><p>Academic records, identity details, photographs and applicable supporting certificates may be requested. Confirm the required documents in the current notice.</p><a class="btn btn-outline" href="#/forms-brochure">Forms &amp; Brochure →</a></div></article><article class="card admission-style-card"><span class="numbered-card-badge">04</span><div class="admission-style-copy"><span class="kicker">Important admission information</span><h2>Use current, approved details.</h2><p>Dates, eligibility, selection criteria, document requirements and fee schedules follow approved information. Check the relevant notice or contact the college before acting.</p><a class="btn btn-outline" href="#/fee-structure">Fee Information</a></div></article><article class="card admission-style-card"><span class="numbered-card-badge">05</span><div class="admission-style-copy"><span class="kicker">Application instructions</span><h2>Apply through the correct destination.</h2><p>Use the programme-specific admission destination where one is listed. The college website does not collect or submit application data.</p><a class="btn btn-primary" href="#/admission-links">Open Admission Link</a><div class="admission-committee-resource">${window.managedPublicDocumentSlot?.('admission_committee')||pendingPdfCard('Admission Committee')}</div></div></article><article class="card admission-style-card"><span class="numbered-card-badge">06</span><div class="admission-style-copy"><span class="kicker">Admission help</span><h2>Ask the college office.</h2><p>For guidance about programmes and the current process, use the enquiry form or contact the college.</p>${enquiryFormButton('Enquiry Form')}</div></article></div></div></section>`)
}

function toggleMobile(){const menu=document.getElementById('mobileMenu');if(!menu)return;const open=menu.classList.toggle('open');document.querySelectorAll('.final-nav .hamb[aria-controls=\"mobileMenu\"]').forEach(button=>{button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?'Close navigation menu':'Open navigation menu')})}

function toggleMobileDropdown(key){const menu=document.getElementById(`mobileSub-${key}`),button=document.querySelector(`.mobile-dropdown-toggle[aria-controls=\"mobileSub-${key}\"]`);if(!menu||!button)return;menu.hidden=!menu.hidden;button.setAttribute('aria-expanded',String(!menu.hidden))}

function footer(){const s={socials:[['Facebook','https://www.facebook.com/shakuntalamcollege/','facebook'],['Instagram','https://www.instagram.com/shakuntalamcollege/','instagram'],['WhatsApp','#/contact','whatsapp']]};return `<footer class="footer"><div class="container footer-grid"><div><a class="footer-reference-brand-lockup" href="#/" aria-label="Shakuntalam College home"><img src="assets/optimized/shakuntalam-brand-lockup-footer.png" alt="Shakuntalam Institute of Teachers Education — Shakuntalam College, established 2015" width="1800" height="440" loading="lazy" decoding="async"></a><p>Quality education, practical learning and student development across teacher education, management and computing.</p><div class="socials footer-socials">${s.socials.filter(x=>!String(x[0]||'').toLowerCase().includes('youtube')).map(x=>{const n=String(x[0]||'').toLowerCase(),asset=n.includes('facebook')?'assets/facebook-logo.png':n.includes('instagram')?'assets/instagram-logo.png':n.includes('whatsapp')?'assets/whatsapp-logo.png':'',href=n.includes('facebook')?'https://www.facebook.com/shakuntalamcollege/':n.includes('instagram')?'https://www.instagram.com/shakuntalamcollege/':n.includes('whatsapp')?'#/contact':x[1],external=href.startsWith('http');if(href==='#')return '';return `<a href="${href}" ${external?'target="_blank" rel="noopener noreferrer"':''} aria-label="${x[0]}">${asset?`<img class="social-brand-icon" src="${asset}" alt="" width="48" height="48" loading="lazy" decoding="async">`:`<span class="social-logo">${socialIcon(x[2])}</span>`}</a>`}).join('')}</div></div><div><h3>Useful Links</h3><a href="https://ugc.gov.in/" target="_blank" rel="noopener noreferrer">UGC</a><a href="https://www.vksu.ac.in/" target="_blank" rel="noopener noreferrer">VKSU</a><a href="https://www.aicte.gov.in/" target="_blank" rel="noopener noreferrer">AICTE</a><a href="https://ncte.gov.in/Website/Index.aspx" target="_blank" rel="noopener noreferrer">NCTE</a><a href="https://www.biharboardonline.org/" target="_blank" rel="noopener noreferrer">Bihar Board</a></div><div><h3>Student Zone</h3><a href="#/admissions">Admission</a><br><a href="#/departments">Departments</a><br><a href="#/examination">Examination</a><br><a href="#/students-zone">Students Zone</a></div><div class="footer-main-address"><h3>Shakuntalam College</h3><p><b>Main Campus :</b> Kirhindih Road, Sasaram, Rohtas-821111</p><p><b>Phone :</b> +91 9470014145&nbsp;&nbsp;+91 8789036195</p><p class="footer-email"><b>Email</b><br><a href="mailto:shakuntalamteacherseducation@gmail.com">shakuntalamteacherseducation@gmail.com</a></p></div></div><section class="container footer-campus-section" aria-label="Campus directions and locations"><div class="footer-campus-intro"><p>Find campus directions and college contact information.</p></div><div class="footer-campus-grid"><article class="footer-campus-card"><iframe title="Map: Shakuntalam Institute of Teachers Education" src="https://www.google.com/maps?cid=7703227135613750179&amp;output=embed" loading="lazy" referrerpolicy="no-referrer-when-downgrade"></iframe><div class="footer-campus-info"><h3>Main Campus</h3><p><b>Shakuntalam Institute of Teachers Education</b><br>Kirhindih Road, Sasaram, Rohtas-821111</p><a href="https://www.google.com/maps?cid=7703227135613750179&amp;g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzEAMYASAF&amp;hl=en&amp;gl=IN&amp;source=embed" target="_blank" rel="noopener noreferrer">Open campus map ↗</a></div></article><article class="footer-campus-card"><iframe title="Map: Shakuntalam College City Campus" src="https://www.google.com/maps?q=24.9538418%2C84.0241586&amp;output=embed" loading="lazy" referrerpolicy="no-referrer-when-downgrade"></iframe><div class="footer-campus-info"><h3>City Campus</h3><p><b>Shakuntalam College (BBA &amp; BCA Department)</b><br>Bauliya More, Jagdev Path, Sasaram, Rohtas-821115</p><a href="https://www.google.com/maps/place/Shakuntalam+College+(BBA+%26+BCA+Department)/@24.9538418,84.0241586,17z/data=!3m1!4b1!4m6!3m5!1s0x398db1ec042ccb39:0xecab3cf3c5d33aa8!8m2!3d24.9538418!4d84.0241586!16s%2Fg%2F11z6jp40pk?hl=en&amp;entry=ttu&amp;g_ep=EgoyMDI2MDkyMy4wIKXMDSoASAFQAw%3D%3D" target="_blank" rel="noopener noreferrer">Open campus map ↗</a></div></article></div></section><div class="container copy"><span>© 2026 Shakuntalam College</span></div></footer>`}

function academics(){const items=[['Academic Programs','B.Ed., D.El.Ed., BBA and BCA provide pathways across teacher education, management and computing.','Explore departments →','/departments'],['Teaching & Learning','Classroom teaching is complemented by practical work, workshops, internships, projects, seminars and guided study.'],['Assessment','Students can follow internal assessment, theory, practical and semester result information through the college.'],['Academic Support','Notices, faculty information, student welfare resources, examination updates and digital student services are available through the website.','Contact Us →','/contact']];return page('Academics','Programs, teaching, assessment and academic support across the college.',`<section class="section"><div class="container academic-info-grid">${items.map((x,i)=>`<article class="card academic-info-card numbered-card"><span class="numbered-card-badge leader-number">0${i+1}</span><h2>${x[0]}</h2><p class="muted">${x[1]}</p>${x[2]?`<a class="btn btn-primary" href="#${x[3]}">${x[2]}</a>`:''}</article>`).join('')}</div></section>`)}

function administration(){return page('Administration','Institutional leadership, offices and administrative services.',`<section class="section"><div class="container leadership-admin-grid"><article class="card leadership-admin-card numbered-card"><span class="numbered-card-badge leader-number">01</span><span class="kicker">Institutional leadership</span><h2>Leadership</h2><p class="muted">Read messages from the Secretary and Principal, and learn about the Governing Body guiding the institution.</p><a class="btn btn-primary" href="#/leadership">Explore leadership →</a></article><article class="card leadership-admin-card numbered-card"><span class="numbered-card-badge leader-number">02</span><span class="kicker">College services</span><h2>Office Services</h2><p class="muted">Admissions, student records, fees, notices, faculty records and student support are coordinated through administrative workflows.</p></article><article class="card leadership-admin-card numbered-card"><span class="numbered-card-badge leader-number">03</span><span class="kicker">Institutional information</span><h2>Transparency</h2><p class="muted">Policies, notices and student-support information can be shared by the college.</p><a class="btn btn-outline" href="#/disclosure">Disclosure</a></article></div></section>`)}

function leadership(){return page('Leadership','Messages and information from the leaders of Shakuntalam College.',`<section class="section leadership-hub"><div class="container"><div class="section-head leadership-section-head"><div><span class="kicker">Institutional leadership</span><h2>Guidance, purpose and shared responsibility.</h2></div><p>Read leadership messages and learn about the society that supports the college.</p></div><div class="leadership-hub-grid"><a class="card leader-card" href="#/leadership/governing-body"><span class="numbered-card-badge leader-number">01</span><span class="kicker">Devi Shakuntalam Pratishthan</span><h3>Governing Body</h3><p>Learn about the society’s history, institutions and commitment to education.</p><span class="leader-action">Explore Governing Body →</span></a><a class="card leader-card" href="#/leadership/founder"><span class="numbered-card-badge leader-number">02</span><span class="kicker">Message from the Founder</span><h3>Founder Desk</h3><p>Read a message from the Society and Institute Founder.</p><span class="leader-action">Visit Founder Desk →</span></a><a class="card leader-card" href="#/leadership/secretary"><span class="numbered-card-badge leader-number">03</span><span class="kicker">Message from the Secretary</span><h3>Secretary Desk</h3><p>Read the Secretary’s message to students, faculty and the college community.</p><span class="leader-action">Visit Secretary Desk →</span></a><a class="card leader-card" href="#/leadership/principal"><span class="numbered-card-badge leader-number">04</span><span class="kicker">Academic leadership</span><h3>Principal Desk</h3><p>Explore the Principal’s welcome and the college’s approach to teaching and learning.</p><span class="leader-action">Visit Principal Desk →</span></a></div></div></section>`)}

function leadershipDesk(which){const desks={founder:{title:'Founder Desk',kicker:'Message from the Founder',greeting:'Dear Students, Faculty and Well-wishers,',paragraphs:[`It gives me great pleasure to welcome every student, faculty member, staff member and well-wisher to the Shakuntalam community. Since Devi Shakuntalam Pratishthan was founded in 2009, our purpose has been to make meaningful education and practical preparation accessible to learners.`,`With this purpose, we established institutions that support teacher education, management, computing and industrial training. Each institution reflects the same belief: knowledge grows stronger when it is joined with practice, discipline and care.`,`Our faculty members guide students with dedication and help them develop confidence, responsibility and respect for others. I encourage every student to approach learning with curiosity, make full use of each opportunity and remain committed to personal growth.`,`Education calls upon us to work together, share ideas and prepare thoughtfully for the changing needs of society. The progress of our institutions is made possible by the efforts of our teachers, staff, students, families and partners.`,`I extend my sincere appreciation to all who contribute to this shared journey and support the college community. May Shakuntalam continue to serve learners with integrity, compassion and a lasting commitment to opportunity.`],name:'Siyaram Singh',role:'Society and Institute Founder'},secretary:{title:'Secretary Desk',kicker:'A message from the Secretary',greeting:'Dear Esteemed Faculty, Staff and Students,',paragraphs:[`It is with great pleasure and pride that I address you as Secretary of our college. As we begin another academic year, I look forward to the opportunities ahead. Shakuntalam College is committed to nurturing future educators who will shape the minds and futures of generations to come. Education is a calling and a responsibility, and we strive for excellence in every part of this work.`,`Our faculty are the backbone of the institution. Their experience, dedication and passion create an environment where knowledge flourishes and future educators are inspired as well as prepared.`,`To our students, welcome. Your journey here is about more than acquiring knowledge: it is also a time for personal growth, character building and developing the skills to become exceptional educators. Make the most of every opportunity to learn and serve.`,`As a college community, let us continue to foster collaboration, innovation and inclusion. To our stakeholders and partners, thank you for your continued support of our mission to provide quality education and prepare educators who are both competent and compassionate.`,`I am confident that, together, we will uphold our commitment to educational innovation and create a positive learning environment. I wish you all a successful and enriching academic year.`],name:'Anil Kumar Singh',role:'Secretary, Devi Shakuntalam Pratishthan'},principal:{title:'Principal Desk',kicker:'A welcome from the Principal',greeting:'Dear Students, Faculty, Staff and Esteemed Guests,',paragraphs:[`It is my pleasure to welcome you to another academic year at Shakuntalam Institute of Teachers Education. Our shared commitment is to foster excellence in education and prepare thoughtful, capable and compassionate educators.`,`Our mission goes beyond traditional academic study. We work to create a learning environment that builds knowledge, a passion for teaching and a strong sense of social responsibility. We want our students to become innovative and effective educators who contribute meaningfully to society.`,`Our experienced faculty bring academic knowledge and practical insight into the classroom. Through theory, practice and guided learning, we aim to help every student develop the skills needed for a changing educational landscape.`,`I encourage you to take an active part in your studies, collaborate with peers and make use of the learning resources and activities available to you. The college community is strengthened by curiosity, mutual support and the lifelong connections formed here.`,`I look forward to seeing each of you grow during your time at Shakuntalam Institute of Teachers Education. May the year ahead be fulfilling and enriching.`],name:'Principal',role:'Shakuntalam Institute of Teachers Education'},'governing-body':{title:'Governing Body',kicker:'Devi Shakuntalam Pratishthan',greeting:'A commitment to educational opportunity since 2009',paragraphs:[`Devi Shakuntalam Pratishthan was founded in 2009 and registered under the Societies Registration Act XXI of 1860 (registration number 2037/2009–10). The society works to expand access to quality education and encourage innovation in learning.`,`In 2015, the society established Shakuntalam Institute of Teachers Education at Kirhindih, Sasaram. The institute’s teacher-education programs include B.Ed., affiliated with VKSU, Ara, and D.El.Ed., affiliated with Bihar School Examination Board, Patna. The institute is recognized by NCTE, ERC Bhubaneswar.`,`The society is committed to well-equipped classrooms, a multipurpose hall, indoor and outdoor activities, and the balanced development of students’ intellectual, personal and social capacities. Its broader aim is to support quality education and create a positive learning environment for the community.`],name:'Devi Shakuntalam Pratishthan',role:'Founded 2009 · Registration No. 2037/2009–10'}};const d=desks[which];if(!d)return leadership();const uploaded='';const portrait=uploaded||(which==='founder'?'assets/founder-portrait-default.png':which==='secretary'?'assets/secretary-portrait-default.png':'');const portraitBlock=['founder','secretary'].includes(which)?portrait?`<figure class="leadership-portrait"><img src="${portrait}" alt="${d.name}" width="720" height="720" loading="lazy" decoding="async"></figure>`:`<figure class="leadership-portrait is-placeholder" aria-label="${d.name} portrait will appear here"><span>AS</span></figure>`:'';const logoBlock=which==='governing-body'?`<img class="leadership-institution-logo" src="assets/optimized/shakuntalam-logo.png" alt="Shakuntalam College official logo" width="600" height="600" loading="lazy" decoding="async">`:'';return page(d.title,d.kicker,`<section class="section leadership-message-section"><div class="container"><a class="back-link" href="#/leadership">← Leadership</a><article class="leadership-message card"><span class="kicker">${d.kicker}</span><h2>${d.greeting}</h2>${d.paragraphs.map(p=>`<p>${p}</p>`).join('')}<div class="leader-signoff"><span>Warm regards,</span>${logoBlock}${portraitBlock}<strong>${d.name}</strong><small>${d.role}</small></div></article></div></section>`)}

function alumniPage(){return page('Alumni','Stay connected with fellow alumni and the Shakuntalam college community.',`<section class="section"><div class="container alumni-page-content"><article class="card alumni-intro-card"><span class="kicker">Shakuntalam Alumni</span><h2>A lasting connection to your college community.</h2><p class="muted">The alumni community brings former students together to stay connected, share experiences and support the next generation of learners. Contact the college for alumni activities and current committee information.</p>${window.managedPublicDocumentSlot?.('alumni_committee')||pendingPdfCard('Alumni Committee')}</article></div></section>`)}

function centreCell(){const complaintFormUrl='https://forms.gle/YcVLgvnuEHZEF5Z98',rtiFormUrl='https://forms.gle/QQaW38Sav4oMMDPG7';return infoPage('Centre & Cells','Student support, safety, grievance and campus committees.',[
 ['Anti-Ragging Cell','The college promotes a safe, respectful environment for every learner.<br>This cell shares awareness about ragging and how to seek support.<br>Students can approach a trusted faculty member or the college office.<br>Ask the administration for current contacts and reporting guidance.','anti_ragging_guidelines'],
 ['Grievance Redressal Cell','A channel for student and staff concerns about college life.<br>Raise questions about academics, facilities, services or support.<br>Share relevant details so the college can understand the matter.<br>Contact the office for current submission and response information.',null,null,'Grievance Redressal Form',complaintFormUrl],
 ['Internal Complaints Committee','The committee supports an inclusive and respectful campus environment.<br>Students and staff can seek information about concerns within its remit.<br>The college office can guide you to the appropriate institutional process.<br>Ask the administration for current committee contacts and procedures.',null,null,'Internal Complaints',complaintFormUrl],
 ['Anti-Sexual Harassment Cell','The college promotes dignity, safety and respectful conduct for all.<br>This cell shares awareness and support information for harassment concerns.<br>Students and staff can seek guidance through the college administration.<br>Contact the office for current support resources and reporting steps.',null,null,'Anti-Sexual Harassment Form',complaintFormUrl],
 ['Student Welfare','Student welfare connects learners with scholarships, notices and support.<br>Students can ask about counselling and available campus resources.<br>Faculty and staff can help direct students to the right service.<br>Contact the college office for current details and eligibility.',null,'/notices','Open Notice Board'],
 ['Admission Committee','The committee coordinates communication about admissions.<br>It reviews application-related matters and supports a clear process.<br>Prospective students can seek guidance through the college office.<br>See the committee document for its published information.','admission_committee'],
 ['Examination Committee','The committee supports examination coordination and academic guidance.<br>It shares relevant information with students about examinations.<br>Students can contact the college office with examination queries.<br>Ask the office for current committee contacts and guidance.','examination_committee'],
 ['Women Committee','The committee promotes awareness, participation and respect.<br>It supports a safe and inclusive campus for women.<br>Students may contact the college about committee support.<br>Ask the office for current contacts and published procedures.','women_committee'],
 ['RIGHT TO INFORMATION (RTI) Appellant','Use the RTI process to request information from the college.<br>State the information you are seeking as clearly as possible.<br>Use the linked form to submit your appeal or information request.<br>For procedural guidance, contact the college office.',null,null,'RTI Form',rtiFormUrl],
 ['Fee Refund Committee','The committee provides guidance on fee-refund matters.<br>Students can contact the college office with refund-related questions.<br>Current procedures and supporting information will be shared when available.<br>Please refer to official college notices for the latest guidance.'],
 ['SC/ST Committee','The committee supports student guidance and inclusion.<br>It helps students find the appropriate college support channel.<br>Students may contact the college office with questions or concerns.<br>Ask the office for current contacts and published procedures.','sc_st_committee'],
 ['Alumni Committee','The committee encourages alumni connection with the college.<br>It supports engagement between graduates and the campus community.<br>Alumni can contact the college office to share updates or enquiries.<br>Ask the office for current committee contacts and activities.','alumni_committee']
])}

const examinationTopics=[
 {slug:'calendar',title:'Examination Calendar',description:'Semester-wise examination dates, internal assessment windows and practical schedules.',detail:'Find semester examination dates, internal assessment windows and practical examination schedules for the academic session.'},
 {slug:'notices',title:'Examination Notices',description:'Important examination circulars, instructions and last dates.',detail:'Review examination circulars, instructions, submission deadlines and other important updates for students.'},
 {slug:'theory-practical',title:'Theory and Practical Exam',description:'Theory and practical examination process, eligibility and conduct rules.',detail:'Read guidance about theory and practical examination arrangements, eligibility, preparation and examination day procedures.'},
 {slug:'regulations',title:'Academic Regulations',description:'Attendance, passing criteria, grading and examination regulations.',detail:'Find the academic regulations that explain attendance requirements, assessment, grading, passing criteria and progression.'},
 {slug:'code-of-conduct',title:'Code of Conduct',description:'Examination rules, guidelines and code of conduct.',detail:'Review the expected conduct, examination rules and guidelines that help maintain a fair and orderly assessment process.'},
 {slug:'pyq-papers',title:'PYQ Papers',description:'Previous year question papers and examination resources.',detail:'Access previous year question papers and related study resources to support examination preparation.'},
 {slug:'committee',title:'Examination Committee',description:'Committee information and published examination guidance.',detail:'The Examination Committee supports examination coordination and academic guidance. Open its published document for further information.',documentKey:'examination_committee'}
];
function examination(){
 const cards=examinationTopics.map((topic,index)=>`<a class="examination-topic-card" href="#/examination/${topic.slug}"><span class="examination-topic-number">${String(index+1).padStart(2,'0')}</span><span class="examination-topic-copy"><h2>${topic.title}</h2><p>${topic.description}</p></span><span class="examination-topic-arrow" aria-hidden="true">→</span></a>`).join('');
 return page('Examination','A complete examination centre for schedules, notices, assessments, results and student services.',`<section class="section examination-topic-section"><div class="container"><div class="examination-topic-grid">${cards}</div></div></section>`)
}
function examinationTopicPage(slug){
 const topic=examinationTopics.find(item=>item.slug===slug);
 if(!topic)return page('Page not found','The page you requested could not be found.','<section class="section"><div class="container"><a class="btn btn-primary" href="#/examination">Return to Examination</a></div></section>');
 const document=topic.documentKey?(window.managedPublicDocumentSlot?.(topic.documentKey)||pendingPdfCard(topic.title)):pendingPdfCard(topic.title);
 return page(topic.title,topic.description,`<section class="section examination-detail-section"><div class="container examination-detail-container"><a class="back-link" href="#/examination">← Examination</a><article class="card examination-topic-detail"><span class="examination-topic-number">${String(examinationTopics.indexOf(topic)+1).padStart(2,'0')}</span><div class="examination-topic-copy"><span class="kicker">Examination resources</span><h2>${topic.title}</h2><p>${topic.detail}</p><div class="examination-detail-documents">${document}</div></div></article></div></section>`)
}

function institutionalResourceCard(icon,kicker,title,description,status,button,href){return `<article class="card resource-card"><span class="resource-card-icon" aria-hidden="true">${icon}</span><div class="resource-card-copy"><span class="kicker">${kicker}</span><h2>${title}</h2><p class="muted">${description}</p></div>${status?`<div class="resource-card-status"><b>Resource status</b><span>${status}</span></div>`:''}<a class="btn btn-outline" href="#${href}">${button} →</a></article>`}

function studentsZone(){const items=[['Student Welfare','Find student support information, welfare resources and guidance for campus concerns.','Student support','student-welfare',`<a class="btn btn-primary" href="#/student-welfare">Explore Student Welfare →</a>`],['Examination','Open examination schedules, academic guidance and published resources.','Academic resources','examination',`<a class="btn btn-primary" href="#/examination">Open Examination Page →</a>`],['Academic Calendar','Review the published academic calendar and related schedules.','Academic planning','academic-calendar',`<a class="btn btn-primary" href="#/academic-calendar">View Academic Calendar →</a>`],['Notices','Read public college announcements and current notices.','College updates','notices',`<a class="btn btn-primary" href="#/notices">Read Notice Board →</a>`]];return page('Students Zone','Public academic information and student support resources.',`<section class="section students-zone-section"><div class="container student-services-grid">${items.map((x,i)=>`<article class="card student-service-card numbered-card"><span class="numbered-card-badge leader-number">0${i+1}</span><div class="student-service-copy"><div class="student-service-heading"><div><span class="kicker">${x[2]}</span><h2>${x[0]}</h2></div></div><p class="muted">${x[1]}</p>${x[4]}</div></article>`).join('')}</div></section>`) }

function iqac(){const pdf=window.managedPublicDocumentGroup?.(['iqac'])||'<p class="muted">No IQAC documents are currently published.</p>';return page('IQAC','Internal Quality Assurance Cell · Quality, reflection and continuous improvement.',`<section class="section"><div class="container"><div class="iqac-intro-grid"><article class="card info-block"><span class="kicker">About the cell</span><h2>Internal Quality Assurance Cell</h2><p class="muted">The IQAC supports a culture of quality in teaching, learning and institutional administration. It encourages regular review of academic practices, constructive feedback and coordinated initiatives that strengthen student outcomes.</p></article><article class="card info-block"><span class="kicker">Our focus</span><h2>Continuous improvement</h2><p class="muted">Through quality planning, documentation and stakeholder participation, the cell helps the institution identify opportunities for improvement and share relevant academic and quality-assurance information.</p></article></div><div class="section-head iqac-documents-heading"><div><span class="kicker">Resources &amp; disclosures</span><h2>IQAC Documents</h2><p class="muted">Published reports, notices and supporting materials from the college.</p></div></div><div class="examination-document-grid iqac-document-grid">${pdf}</div></div></section>`)}
function faculty(){return page('List of Faculty','Browse faculty information by programme.',`<section class="section"><div class="container faculty-document-page">${window.managedPublicDocumentGroup?window.managedPublicDocumentGroup(['bed_faculty','deled_faculty','bba_faculty','bca_faculty']):''}</div></section>`)}

function studentWelfare(){return centreCell()}

function nssPage(){return page('National Service Scheme (NSS)','Student volunteering, community engagement and service activities.',`<section class="section"><div class="container">${window.managedPublicDocumentGroup?window.managedPublicDocumentGroup(['nss']):''}</div></section>`)}

function infoPage(title,sub,sections){return page(title,sub,`<section class="section"><div class="container info-long ${title==='Centre & Cells'?'centre-cell-list':''}">${sections.map((x,i)=>{const document=x[2]?window.managedPublicDocumentSlot?.(x[2])||pendingPdfCard(x[0]):'',notice=x[5]?`<a class="btn btn-primary" href="${escapeHtml(x[5])}" target="_blank" rel="noopener noreferrer">${escapeHtml(x[4]||'Open form')} ↗</a>`:x[3]?`<a class="btn btn-outline" href="#${x[3]}">${escapeHtml(x[4]||'View notices')} →</a>`:'';return `<article class="card info-block numbered-card"><span class="numbered-card-badge leader-number">${String(i+1).padStart(2,'0')}</span><h2>${escapeHtml(x[0])}</h2><p class="muted">${x[1]}</p>${notice?`<div class="info-block-actions">${notice}</div>`:''}${document?`<div class="student-safety-document-wrap">${document}</div>`:''}</article>`}).join('')}</div></section>`) }

function scrollPageToTop(){
  const jump=()=>{window.scrollTo(0,0);document.documentElement.scrollTop=0;document.body.scrollTop=0;};
  jump();
  requestAnimationFrame(jump);
  setTimeout(jump,0);
  setTimeout(jump,120);
}

function escapeHtml(v){return String(v||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}

