function homeHeroCarouselMarkup(){
  const slides=HERO_SLIDES;
  const first=slides[0]?.image||'';
  return `<div class="hero-card hero-card-placeholder" aria-label="Shakuntalam College hero image carousel"><div class="hero-carousel-stage" data-hero-stage tabindex="0" role="region" aria-roledescription="carousel" aria-label="Homepage images"><img id="heroCarouselImage" src="${escapeHtml(first)}" alt="Shakuntalam College campus in Sasaram" class="home-image" width="1444" height="1084" loading="eager" fetchpriority="high" decoding="async"><button type="button" class="hero-arrow hero-prev" aria-label="Previous image" onclick="nextHeroSlideV7(-1)">‹</button><button type="button" class="hero-arrow hero-next" aria-label="Next image" onclick="nextHeroSlideV7(1)">›</button>${slides.length>1?`<div class="hero-dots">${slides.map((_,i)=>`<button type="button" class="hero-dot ${i===0?'active':''}" aria-label="Show hero image ${i+1}" onclick="showHeroSlideV7(${i});return false"></button>`).join('')}</div>`:''}</div></div>`;
}

function homeFeatureCarouselMarkup(key,slides,alt){
  const safeSlides=(slides||[]).filter(x=>x&&x.image);
  const first=safeSlides[0]?.image||'';
  return `<div class="home-feature-carousel-frame" data-home-carousel="${key}" data-index="0" aria-label="${escapeHtml(alt)} image carousel"><img class="home-image" src="${escapeHtml(first)}" alt="${escapeHtml(safeSlides[0]?.title||alt)}" width="1444" height="1084" loading="lazy" decoding="async"><button type="button" class="home-carousel-arrow previous" aria-label="Previous ${escapeHtml(alt)} image" onclick="stepHomeImageCarousel('${key}',-1)">‹</button><button type="button" class="home-carousel-arrow next" aria-label="Next ${escapeHtml(alt)} image" onclick="stepHomeImageCarousel('${key}',1)">›</button>${safeSlides.length>1?`<div class="home-carousel-dots">${safeSlides.map((_,i)=>`<button type="button" class="home-carousel-dot ${i===0?'active':''}" aria-label="Show ${escapeHtml(alt)} image ${i+1}" onclick="showHomeImageSlide('${key}',${i},1)"></button>`).join('')}</div>`:''}</div>`;
}

