function accreditationHubPage(){const html=institutionalHubPage('Accreditation & Quality Assurance','Information and documentation relating to institutional quality assurance.',[['Accreditation','NAAC','Information and documentation related to institutional accreditation.','','View NAAC Information','/accreditation/naac'],['Quality assurance','IQAC','Information related to the Internal Quality Assurance Cell.','','View IQAC','/iqac'],['Submissions','IIQA','Information and documentation related to institutional quality-assurance submissions.','','View IIQA Information','/accreditation/iiqa']]);if(!window.managedPublicDocumentGroup)return html;const at=html.lastIndexOf('</section>');return at<0?html:html.slice(0,at)+`<div class="container accreditation-document-wrap">${window.managedPublicDocumentGroup(['aicte_approvals'],'AICTE Approvals')}</div>`+html.slice(at)}


function updateRouteMetadata(path){
 const heading=app.querySelector('h1');
 let pageTitle=(heading?.textContent||'Shakuntalam Institute of Teachers Education').replace(/\s+/g,' ').trim();
 if(path==='/student-welfare')pageTitle='Student Welfare';
 if(path==='/course/Electrician')pageTitle='Electrician Course Information';
 if(path==='/course/Fitter')pageTitle='Fitter Course Information';
 let summary=(app.querySelector('.course-overview-content .course-lead')||app.querySelector('.page-hero p'))?.textContent||'Official website of Shakuntalam Institute of Teachers Education in Sasaram, Bihar.';
 if(path==='/student-welfare')summary='Student support, safety, grievance and welfare information for the Shakuntalam College community.';
 if(path==='/course/Electrician')summary='Current Electrician programme details are unavailable; contact the college for the latest course information.';
 if(path==='/course/Fitter')summary='Current Fitter programme details are unavailable; contact the college for the latest course information.';
 summary=summary.replace(/\s+/g,' ').trim();
 const description=summary.length>180?summary.slice(0,177).replace(/\s+\S*$/,'')+'…':summary;
 document.title=path==='/'?'Shakuntalam Institute of Teachers Education | Shakuntalam College':`${pageTitle} | Shakuntalam College`;
 const setMeta=(selector,content,create)=>{let el=document.head.querySelector(selector);if(!el&&create){el=document.createElement('meta');Object.entries(create).forEach(([k,v])=>el.setAttribute(k,v));document.head.append(el)}if(el)el.setAttribute('content',content)};
 setMeta('meta[name="description"]',description);
 const cfg=JSON.parse(document.getElementById('site-seo-config')?.textContent||'{"siteBaseUrl":""}');
 const base=String(cfg.siteBaseUrl||'').replace(/\/$/,'');
 const canonical=document.head.querySelector('link[rel="canonical"]');if(canonical)canonical.remove();
 if(base&&path==='/'){const link=document.createElement('link');link.rel='canonical';link.href=base+'/';document.head.append(link)}
 const blocked=path==='/404'||pageTitle==='Page not found';setMeta('meta[name="robots"]',blocked?'noindex,follow':'index,follow');
 const ogTitle=document.title;
 setMeta('meta[property="og:title"]',ogTitle);setMeta('meta[property="og:description"]',description);setMeta('meta[property="og:type"]','website');setMeta('meta[property="og:site_name"]','Shakuntalam College');
 setMeta('meta[name="twitter:card"]','summary_large_image');setMeta('meta[name="twitter:title"]',ogTitle);setMeta('meta[name="twitter:description"]',description);
 const setUrlMeta=(selector,value,create)=>{let el=document.head.querySelector(selector);if(!base){el?.remove();return}if(!el){el=document.createElement('meta');Object.entries(create).forEach(([k,v])=>el.setAttribute(k,v));document.head.append(el)}el.setAttribute('content',value)};
 const pageUrl=base?base+'/'+(location.hash?location.hash:''):'';
 setUrlMeta('meta[property="og:url"]',pageUrl,{'property':'og:url'});setUrlMeta('meta[property="og:image"]',base?base+'/assets/shakuntalam-open-graph.png':'',{'property':'og:image'});
 if(base){let alt=document.head.querySelector('meta[property="og:image:alt"]');if(!alt){alt=document.createElement('meta');alt.setAttribute('property','og:image:alt');document.head.append(alt)}alt.content='Shakuntalam Institute of Teachers Education college brand card'}else document.head.querySelector('meta[property="og:image:alt"]')?.remove();
 setUrlMeta('meta[name="twitter:image"]',base?base+'/assets/shakuntalam-open-graph.png':'',{'name':'twitter:image'});
 const data=document.getElementById('institution-jsonld');if(data){const schema=JSON.parse(data.textContent);if(base){schema.url=base+'/';schema.logo=base+'/assets/optimized/shakuntalam-brand-lockup.png'}else{delete schema.url;delete schema.logo}data.textContent=JSON.stringify(schema)}
}

function route(){const path=location.hash.replace(/^#/,'')||'/';let content='';if(path==='/')content=home();else if(path==='/about')content=about();else if(path==='/mission')content=mission();else if(path==='/departments')content=departments();else if(path==='/academics')content=academics();else if(path==='/admission-policy')content=admissionPolicyPage();else if(path==='/course-eligibility')content=courseEligibilityPage();else if(path==='/forms-brochure')content=formsBrochurePage();else if(path==='/fee-structure')content=feeStructurePage();else if(path==='/admission-links')content=admissionLinks();else if(path==='/syllabus')content=syllabusPage();else if(path==='/information')content=informationHubPage();else if(path==='/add-information')content=additionalInformationPage();else if(path==='/disclosure')content=disclosureHubPage();else if(path==='/accreditation')content=accreditationHubPage();else if(path==='/academic-calendar')content=academicCalendarPage('Academic Calendar','');else if(path==='/academic-calendar/holidays')content=academicCalendarPage('Holidays','holidays');else if(path==='/academic-calendar/class-timetable')content=academicCalendarPage('Class Timetable','class-timetable');else if(path==='/information/audit-report')content=informationDocumentPage('audit-report');else if(path==='/information/annual-report')content=informationDocumentPage('annual-report');else if(path==='/information/institutional-certificates')content=informationDocumentPage('institutional-certificates');else if(path==='/information/university-affiliation')content=informationDocumentPage('university-affiliation');else if(path==='/disclosure/information')content=informationDocumentPage('disclosure-information');else if(path==='/disclosure/fixed-deposits')content=informationDocumentPage('fixed-deposits');else if(path==='/disclosure/affidavits')content=informationDocumentPage('affidavits');else if(path==='/disclosure/building-land-documents')content=informationDocumentPage('building-land-documents');else if(path==='/accreditation/naac')content=informationDocumentPage('naac');else if(path==='/accreditation/iiqa')content=informationDocumentPage('iiqa');else if(path==='/administration')content=administration();else if(path==='/leadership')content=leadership();else if(path==='/leadership/founder')content=leadershipDesk('founder');else if(path==='/leadership/secretary')content=leadershipDesk('secretary');else if(path==='/leadership/principal')content=leadershipDesk('principal');else if(path==='/leadership/governing-body')content=leadershipDesk('governing-body');else if(path==='/centre-cell')content=centreCell();else if(path==='/alumni')content=alumniPage();else if(path==='/examination')content=examination();else if(path.startsWith('/examination/'))content=examinationTopicPage(path.split('/')[2]);else if(path==='/events')content=events();else if(path.startsWith('/events/'))content=eventDetailPage(path.split('/')[2]);else if(path==='/students-zone')content=studentsZone();else if(path==='/iqac')content=iqac();else if(path==='/faculty')content=faculty();else if(path==='/student-welfare')content=studentWelfare();else if(path==='/nss')content=nssPage();else if(path.startsWith('/department/'))content=publicDepartment(decodeURIComponent(path.split('/')[2]));else if(path.startsWith('/course/'))content=course(decodeURIComponent(path.split('/')[2]));else if(path==='/notices')content=notices();else if(path.startsWith('/facilities/'))content=facilityDetailPage(path.split('/')[2]);else if(path==='/facilities')content=facilities();else if(path==='/gallery')content=gallery();else if(path==='/contact')content=contact();else if(path==='/admissions')content=admissions();else if(path==='/404')content=page('Page not found','The page you requested could not be found.','<section class="section"><div class="container"><a class="btn btn-primary" href="#/">Return home</a></div></section>');else content=page('Page not found','The page you requested could not be found.','<section class="section"><div class="container"><a class="btn btn-primary" href="#/">Return home</a></div></section>');app.innerHTML=content;updateRouteMetadata(path);if(typeof startPublicCarousels==='function')startPublicCarousels();scrollPageToTop()}
window.addEventListener('hashchange',route);
window.addEventListener('DOMContentLoaded',route);
